function field(string $name,int $max=255): string {return trim(mb_substr((string)($_POST[$name]??''),0,$max));}
function fail(string $message,int $code=400): never {http_response_code($code);page('Errore','<div class="card"><h1>Operazione non riuscita</h1><p>'.C::h($message).'</p><p><a href="/">Torna all’area clienti</a></p></div>');exit;}
function page(string $title,string $content,?array $user=null): void {$siteUrl=C::h((string)(C::config()['site_url']??'https://caautomazione.github.io/'));$name=$user?C::h($user['first_name'].' '.$user['last_name']):'';$nav=$user?'<div class="user">'.$name.' · '.($user['role']==='admin'?'Amministrazione':($user['role']==='operator'?'Operatore CA Automazione':'Cliente')).' <form method="post" action="/?action=logout"><input type="hidden" name="_csrf" value="'.C::csrf().'"><button class="link">Esci</button></form></div>':'';if($user&&isset($_SESSION['impersonator_uid']))$content='<div class="impersonation"><strong>Vista del cliente '.C::h($user['first_name'].' '.$user['last_name']).'</strong><span>Accesso amministrativo registrato. I download del cliente sono disattivati in questa vista.</span><form method="post" action="/?action=stop_impersonation">'.inputCsrf().'<button class="subtle">Torna all’amministrazione</button></form></div>'.$content;echo '<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta http-equiv="Cache-Control" content="no-store"><title>'.C::h($title).' · C.A. Automazione &amp; Strumentazione</title><link rel="icon" href="/assets/logo-quadrato.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script src="/portal.js" defer></script></head><body><header><div class="shell top"><a class="brand" href="/" aria-label="C.A. Automazione &amp; Strumentazione · Area Clienti"><img src="/assets/logo-quadrato.svg" alt=""><span>C.A. Automazione &amp; Strumentazione<small>Area Clienti</small></span></a><div class="top-actions"><a class="back-site" href="'.$siteUrl.'">Torna al sito internet</a>'.$nav.'</div></div></header><main class="shell">'.$content.'</main></body></html>';}
function inputCsrf(): string {return '<input type="hidden" name="_csrf" value="'.C::csrf().'">';}
function cleanFilename(string $name): string {$name=basename(str_replace('\\','/',$name));return mb_substr(preg_replace('/[\x00-\x1f\x7f]/u','',$name) ?: 'documento',0,180);}
function document(int $id,array $u): array|false {return C::row('SELECT d.* FROM documents d JOIN users r ON r.id=d.recipient_id AND r.active=1 AND r.deleted_at IS NULL JOIN companies c ON c.id=d.company_id AND c.active=1 JOIN plants p ON p.id=d.plant_id AND p.active=1 WHERE d.id=? AND d.deleted_at IS NULL AND d.revoked_at IS NULL AND ( ? IN (\'admin\',\'operator\') OR (d.recipient_id=? AND d.company_id=? AND EXISTS(SELECT 1 FROM user_plants up WHERE up.user_id=? AND up.plant_id=d.plant_id)))',[$id,$u['role'],$u['id'],$u['company_id'],$u['id']]);}
