 if($tab==='documents'&&$u['role']!=='client'){$people=C::all("SELECT u.id,u.first_name,u.last_name,u.email,u.company_id,p.id plant_id,p.name plant,c.name company FROM users u JOIN companies c ON c.id=u.company_id JOIN user_plants up ON up.user_id=u.id JOIN plants p ON p.id=up.plant_id WHERE u.role='client' AND u.active=1 AND u.deleted_at IS NULL AND c.active=1 AND p.active=1 ORDER BY c.name,u.last_name");$opts='';foreach($people as $p)$opts.='<option value="'.$p['id'].':'.$p['plant_id'].'">'.C::h($p['first_name'].' '.$p['last_name'].' · '.$p['company'].' / '.$p['plant'].' · '.$p['email']).'</option>';$body.='<section class="card"><h2>Carica un documento</h2><p>Seleziona una sola persona. Il suo nome e l’impianto sono mostrati insieme per evitare consegne errate.</p><form method="post" action="/?action=upload" enctype="multipart/form-data" id="upload">'.inputCsrf().'<div class="formgrid"><label>Titolo<input name="title" maxlength="220" required></label><label>Destinatario<select id="recipient" required><option value="">Seleziona una persona</option>'.$opts.'</select></label></div><input type="hidden" name="recipient_id" id="rid"><input type="hidden" name="plant_id" id="pid"><label>File<input type="file" name="file" required></label><button class="primary">Conferma e invia notifica</button></form><script>document.getElementById("upload").addEventListener("submit",e=>{let v=document.getElementById("recipient").value.split(":");if(v.length!==2){e.preventDefault();return}document.getElementById("rid").value=v[0];document.getElementById("pid").value=v[1];if(!confirm("Confermi la consegna a "+document.getElementById("recipient").selectedOptions[0].text+"?"))e.preventDefault()})</script></section>';$docs=C::all('SELECT d.*,u.first_name,u.last_name,u.email,c.name company,p.name plant FROM documents d JOIN users u ON u.id=d.recipient_id JOIN companies c ON c.id=d.company_id JOIN plants p ON p.id=d.plant_id WHERE d.deleted_at IS NULL ORDER BY d.created_at DESC LIMIT 200');}
 elseif($tab==='documents'||$tab==='archive'){$sql='SELECT d.*,p.name plant FROM documents d JOIN plants p ON p.id=d.plant_id JOIN companies c ON c.id=d.company_id WHERE d.recipient_id=? AND d.company_id=? AND d.deleted_at IS NULL AND d.revoked_at IS NULL AND c.active=1 AND p.active=1 AND EXISTS(SELECT 1 FROM user_plants up WHERE up.user_id=? AND up.plant_id=d.plant_id) AND d.first_download_at IS '.($tab==='archive'?'NOT NULL':'NULL').' ORDER BY d.created_at DESC';$docs=C::all($sql,[$u['id'],$u['company_id'],$u['id']]);}
 if(isset($docs)){$body.='<section class="card"><h2>'.($u['role']!=='client'?'Documenti consegnati':($tab==='archive'?'Archivio':'Da scaricare')).'</h2><div class="table-tools"><label>Cerca in questa sezione<input type="search" class="table-search" placeholder="Cerca per nome, documento, azienda o impianto" autocomplete="off"></label><span class="search-count" aria-live="polite"></span></div><div class="scroll"><table><thead><tr><th>Documento</th><th>'.($u['role']!=='client'?'Destinatario':'Impianto').'</th><th>Caricato</th><th>Stato / Azioni</th></tr></thead><tbody>';foreach($docs as $d){$body.='<tr><td><strong>'.C::h($d['title']).'</strong><small>'.C::h($d['original_name']).' · '.number_format($d['bytes']/1048576,1,',','.').' MB</small></td><td>'.($u['role']!=='client'?C::h($d['first_name'].' '.$d['last_name']).'<small>'.C::h($d['email'].' · '.$d['company'].' / '.$d['plant']).'</small>':C::h($d['plant'])).'</td><td>'.C::date($d['created_at']).'</td><td>';if($d['revoked_at'])$body.='<span class="pill">Revocato</span>';else{$body.='<a href="/?action=view&id='.$d['id'].'" target="_blank" rel="noopener">Visualizza</a> · <a href="/?action=download&id='.$d['id'].'">Scarica</a>';}if($u['role']!=='client')$body.='<details><summary>Modifica titolo</summary><form method="post" action="/?action=edit_document">'.inputCsrf().'<input type="hidden" name="id" value="'.$d['id'].'"><input name="title" value="'.C::h($d['title']).'" required maxlength="220"><button class="subtle">Salva</button></form></details><small>'.($d['first_download_at']?'Primo download: '.C::date($d['first_download_at']):'Da scaricare').'</small><form method="post" action="/?action=revoke" onsubmit="return confirm(\'Revocare l’accesso al documento?\')">'.inputCsrf().'<input type="hidden" name="id" value="'.$d['id'].'"><button class="subtle">Revoca accesso</button></form>'; $body.='</td></tr>';}if(!$docs)$body.='<tr><td colspan="4">Nessun documento in questa sezione.</td></tr>';$body.='</tbody></table></div></section>';}
 if($tab==='accounts'&&$u['role']==='admin'){$companies=C::all('SELECT * FROM companies ORDER BY name');$plants=C::all('SELECT p.*,c.name company FROM plants p JOIN companies c ON c.id=p.company_id ORDER BY c.name,p.name');$users=C::all("SELECT u.*,c.name company FROM users u JOIN companies c ON c.id=u.company_id WHERE u.role='client' AND u.deleted_at IS NULL ORDER BY c.name,u.last_name");$co='';foreach($companies as $c)$co.='<option value="'.$c['id'].'">'.C::h($c['name']).'</option>';$po='';foreach($plants as $p)$po.='<option value="'.$p['id'].'" data-company="'.$p['company_id'].'">'.C::h($p['company'].' / '.$p['name']).'</option>';$body.='<div class="cols"><section class="card"><h2>Nuova azienda</h2><form method="post" action="/?action=company">'.inputCsrf().'<label>Nome<input name="name" required></label><button class="primary">Aggiungi azienda</button></form></section><section class="card"><h2>Nuovo impianto</h2><form method="post" action="/?action=plant">'.inputCsrf().'<label>Azienda<select name="company_id" required>'.$co.'</select></label><label>Nome impianto<input name="name" required></label><button class="primary">Aggiungi impianto</button></form></section></div><section class="card"><h2>Nuovo account cliente</h2><p>Consegna la password iniziale alla persona attraverso un canale sicuro. Il cliente potrà cambiarla dopo l’accesso.</p><form method="post" action="/?action=account">'.inputCsrf().'<div class="formgrid"><label>Nome<input name="first_name" required></label><label>Cognome<input name="last_name" required></label><label>Email<input name="email" type="email" required></label><label>Password iniziale<input name="password" type="password" minlength="12" required></label><label>Azienda<select name="company_id" id="company" required><option value="">Seleziona</option>'.$co.'</select></label><label>Impianto<select name="plant_id" id="plant" required><option value="">Seleziona</option>'.$po.'</select></label></div><button class="primary">Crea account</butto