  $body.='<section class="card"><h2>Modifica account e permessi</h2><p>Apri una persona per aggiornare i dati e gli impianti consentiti.</p><div class="table-tools"><label>Cerca clienti<input type="search" class="account-search" placeholder="Cerca nome, email o azienda" autocomplete="off"></label><span class="search-count" aria-live="polite"></span></div><div class="account-list">';
