  }$body.='</div></section><section class="card"><h2>Accessi recenti</h2><p>Ora italiana e indirizzo IP visto dal server. L’indirizzo IP non indica con certezza la posizione fisica.</p><div class="table-tools"><label>Cerca in questa sezione<input type="search" class="table-search" placeholder="Cerca per nome, documento, azienda o impianto" autocomplete="off"></label><span class="search-count" aria-live="polite"></span></div><div class="scroll"><table><thead><tr><th>Persona</th><th>Data e ora</th><th>Indirizzo IP</th><th>Browser</th></tr></thead><tbody>';foreach(array_slice($access,0,100) as $event){$name=C::row('SELECT first_name,last_name FROM users WHERE id=?',[$event['user_id']]);$body.='<tr><td>'.C::h($name?($name['first_name'].' '.$name['last_name']):'Account rimosso').'</td><td>'.C::date($event['occurred_at']).'</td><td>'.C::h($event['ip']?inet_ntop($event['ip']):'Non disponibile').'</td><td><small>'.C::h(mb_substr($event['user_agent']??'',0,130)).'</small></td></tr>';}if(!$access)$body.='<tr><td colspan="4">Nessun accesso registrato.</td></tr>';$body.='</tbody></table></div></section>';
 }
 if($tab==='events'&&$u['role']==='admin'){$events=C::all('SELECT e.*,d.title,u.first_name,u.last_name,u.email,c.name company,p.name plant FROM download_events e JOIN documents d ON d.id=e.document_id JOIN users u ON u.id=e.user_id JOIN companies c ON c.id=d.company_id JOIN plants p ON p.id=d.plant_id ORDER BY e.started_at DESC LIMIT 300');$body.='<section class="card"><h2>Download registrati</h2><p>La data indica l’avvio della trasmissione dal server, non la conferma del salvataggio sul dispositivo.</p><div class="table-tools"><label>Cerca in questa sezione<input type="search" class="table-search" placeholder="Cerca per nome, documento, azienda o impianto" autocomplete="off"></label><span class="search-count" aria-live="polite"></span></div><div class="scroll"><table><thead><tr><th>Documento</th><th>Persona</th><th>Azienda / impianto</th><th>Data e ora (Italia)</th></tr></thead><tbody>';foreach($events as $e)$body.='<tr><td>'.C::h($e['title']).'</td><td>'.C::h($e['first_name'].' '.$e['last_name']).'<small>'.C::h($e['email']).'</small></td><td>'.C::h($e['company'].' / '.$e['plant']).'</td><td>'.C::date($e['started_at']).'</td></tr>';$body.='</tbody></table></div></section>';}
